contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function taking the createGameItem parameters
    function run(string memory name_, string memory tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public payable {
        // observe before state
        uint256 beforeUnique = c.uniqueTokensOutstanding(); if (__ESBMC_reverted()) return;

        // Attempt the state-changing call at top-level and capture revert via try/catch flag
        bool didRevert;
        c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // observe after state
        uint256 afterUnique = c.uniqueTokensOutstanding(); if (__ESBMC_reverted()) return;

        // Build the single general assertion combining both cases
        // If reverted then unique count unchanged. If not reverted then unique increased exactly by 1
        // and for the new token (id = beforeUnique) if finiteSupply true then remainingSupply equals itemsRemaining.
        uint256 newId = beforeUnique;
        uint256 remForNew = c.remainingSupply(newId); if (__ESBMC_reverted()) return;

        assert(
            (didRevert && afterUnique == beforeUnique)
            ||
            (!didRevert && afterUnique == beforeUnique + 1 && (finiteSupply ? remForNew == itemsRemaining : true))
        );
    }

    receive() external payable {}
}

