pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(string memory name_, string memory tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) internal {
        uint256 beforeUnique;
        try c.uniqueTokensOutstanding() returns (uint256 __r) { beforeUnique = __r; } catch { return; }
        bool didRevert;
        try c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance) {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        uint256 afterUnique;
        try c.uniqueTokensOutstanding() returns (uint256 __r) { afterUnique = __r; } catch { return; }
        uint256 newId = beforeUnique;
        uint256 remForNew;
        try c.remainingSupply(newId) returns (uint256 __r) { remForNew = __r; } catch { return; }
        assertTrue((didRevert && afterUnique == beforeUnique)
            ||
            (!didRevert && afterUnique == beforeUnique + 1 && (finiteSupply ? remForNew == itemsRemaining : true)));
    }

    function testFuzz_run(string memory name_, string memory tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public {
        _run(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);
    }

    receive() external payable {}
}
